"use client";
import {ArtemisScope} from "./artemis-scope";
import View2 from "./components/performance-report/variants/03-team";
const views={"team":View2};
export interface ArtemisPerformanceReportProps {className?:string;variant?:"team";}
export function ArtemisPerformanceReport({className,variant="team"}:ArtemisPerformanceReportProps){const View=views[variant];return <ArtemisScope className={className}><View/></ArtemisScope>;}

"use client";
// @zeus-internal
import { CalendarDays, Users } from "lucide-react";
import { motion, useReducedMotion } from "motion/react";
import { useMemo, useState } from "react";
import { ARTEMIS_EASE_OUT, ARTEMIS_SPRING_PRESS } from "../../../lib/ease";
import { ChoiceMenu } from "./03-team/choice-menu";
import { change, pct, type Row, rowFor, TEAM_OPTIONS, TEAMMATES, type TeamId, WINDOW_OPTIONS, WINDOWS, type WindowId } from "./03-team/data";
import { TeammateDialog } from "./03-team/detail-dialog";
import { Roller } from "./03-team/roller";
type SortKey = "name" | "delivered" | "firstReply" | "onTime" | "reviews";
type Sort = {
    key: SortKey;
    dir: "asc" | "desc";
};
const COLUMNS: ReadonlyArray<{
    key: SortKey;
    label: string;
}> = [
    { key: "name", label: "Teammate" },
    { key: "delivered", label: "Delivered" },
    { key: "firstReply", label: "First reply" },
    { key: "onTime", label: "On-time replies" },
    { key: "reviews", label: "Reviews passed" },
];
const TEAM_NAMES: Record<Exclude<TeamId, "all">, string> = { care: "Customer care", ops: "Operations" };
const TH_CLASS = "art:sticky art:top-0 art:z-10 art:h-11 art:border-border art:border-b art:bg-muted art:px-4 art:font-medium art:text-muted-foreground art:text-xs";
const CELL_CLASS = "art:absolute art:inset-0 art:flex art:min-w-0 art:items-center art:overflow-hidden art:px-4";
const VIEW_BUTTON_CLASS = "art:inline-flex art:items-center art:justify-center art:font-medium art:select-none art:transition-colors art:disabled:pointer-events-none art:disabled:opacity-50 art:text-muted-foreground art:hover:bg-primary/5 art:hover:text-foreground art:gap-2 art:text-sm art:focus-visible:ring-offset-2 art:focus-visible:ring-offset-background art:ml-auto art:size-9 art:p-0 art:focus-visible:outline-none art:focus-visible:ring-2 art:focus-visible:ring-ring art:rounded-full";
const METRIC_CLASS = "art:@container/metric art:flex art:min-w-0 art:flex-col art:justify-between art:bg-background art:p-4 art:@lg:flex-1 art:gap-5 art:@lg:min-w-56";
const ICON_WRAP_CLASS = "art:grid art:size-9 art:shrink-0 art:place-items-center art:rounded-full art:border art:border-border art:bg-muted art:text-muted-foreground art:[&>svg]:size-4";
const DT_CLASS = "art:min-w-0 art:flex-1 art:whitespace-nowrap art:font-mono art:uppercase art:tracking-tight art:text-muted-foreground art:text-sm art:font-normal";
const DD_CLASS = "art:flex art:flex-col art:items-start art:gap-x-4 art:gap-y-2 art:@sm/metric:flex-row art:@sm/metric:flex-wrap art:@sm/metric:items-center art:@sm/metric:justify-between";
const VALUE_CLASS = "art:inline-flex art:items-baseline art:whitespace-nowrap art:text-3xl art:font-medium art:tabular-nums art:tracking-tight";
const ratio = ([part, whole]: [
    number,
    number
]) => part / whole;
const grouped = (n: number) => n.toLocaleString("en-US");
function compare(key: SortKey, a: Row, b: Row): number {
    switch (key) {
        case "name":
            return a.teammate.name.localeCompare(b.teammate.name);
        case "delivered":
            return a.delivered - b.delivered;
        case "firstReply":
            return a.firstReplyMinutes - b.firstReplyMinutes;
        case "onTime":
            return ratio(a.replies) - ratio(b.replies);
        case "reviews":
            return ratio(a.reviews) - ratio(b.reviews);
    }
}
function SortIcon({ state }: {
    state: "asc" | "desc" | null;
}) {
    if (state === "asc")
        return (<svg xmlns="http://www.w3.org/2000/svg" width="24" height="24" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round" className="art:lucide art:lucide-chevron-up art:size-3.5" aria-hidden="true">
        <path d="m18 15-6-6-6 6"/>
      </svg>);
    if (state === "desc")
        return (<svg xmlns="http://www.w3.org/2000/svg" width="24" height="24" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round" className="art:lucide art:lucide-chevron-down art:size-3.5" aria-hidden="true">
        <path d="m6 9 6 6 6-6"/>
      </svg>);
    return (<svg xmlns="http://www.w3.org/2000/svg" width="24" height="24" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round" className="art:lucide art:lucide-chevrons-up-down art:size-3.5 art:opacity-45" aria-hidden="true">
      <path d="m7 15 5 5 5-5"/>
      <path d="m7 9 5-5 5 5"/>
    </svg>);
}
function DeltaTicker({ value }: {
    value: string;
}) {
    const positive = value.startsWith("+");
    return (<Roller className="art:inline-flex art:items-baseline art:tabular-nums art:whitespace-nowrap" prefix={positive ? "+" : undefined} text={positive ? value.slice(1) : value} suffix="%"/>);
}
function OnTimeBar({ value }: {
    value: number;
}) {
    const reduce = useReducedMotion();
    return (<motion.div className="art:h-full art:origin-left art:rounded-full art:bg-primary" initial={reduce ? false : { scaleX: 0 }} animate={{ scaleX: value }} transition={reduce ? { duration: 0 } : { duration: 0.53, ease: ARTEMIS_EASE_OUT }}/>);
}
export default function PerformanceReportTeam() {
    const reduce = useReducedMotion();
    const [team, setTeam] = useState<TeamId>("all");
    const [windowId, setWindowId] = useState<WindowId>("28");
    const [query, setQuery] = useState("");
    const [focused, setFocused] = useState(false);
    const [sort, setSort] = useState<Sort>({ key: "delivered", dir: "desc" });
    const [openName, setOpenName] = useState<string | null>(null);
    const info = WINDOWS[windowId];
    const ranked = useMemo(() => TEAMMATES.filter((t) => team === "all" || t.team === TEAM_NAMES[team])
        .map((t) => rowFor(t, windowId))
        .sort((a, b) => b.delivered - a.delivered), [team, windowId]);
    const shown = useMemo(() => {
        const needle = query.toLowerCase();
        const matches = ranked
            .map((row, i) => ({ row, rank: i + 1 }))
            .filter(({ row }) => `${row.teammate.name} ${row.teammate.role} ${row.teammate.team}`.toLowerCase().includes(needle));
        const sign = sort.dir === "asc" ? 1 : -1;
        return [...matches].sort((a, b) => sign * compare(sort.key, a.row, b.row) || a.rank - b.rank);
    }, [ranked, query, sort]);
    const totals = useMemo(() => {
        const add = (pick: (r: Row) => number) => ranked.reduce((acc, r) => acc + pick(r), 0);
        const delivered = add((r) => r.delivered);
        return {
            delivered,
            change: change(delivered, add((r) => r.previousDelivered)),
            replies: [add((r) => r.replies[0]), add((r) => r.replies[1])] as [
                number,
                number
            ],
            reviews: [add((r) => r.reviews[0]), add((r) => r.reviews[1])] as [
                number,
                number
            ],
        };
    }, [ranked]);
    const openRow = openName ? (rowFor(TEAMMATES.find((t) => t.name === openName) ?? TEAMMATES[0], windowId)) : null;
    const toggleSort = (key: SortKey) => setSort((prev) => (prev.key === key ? { key, dir: prev.dir === "asc" ? "desc" : "asc" } : { key, dir: "asc" }));
    return (<>
      <div className="art:w-full art:max-w-7xl">
        <section aria-labelledby="_R_pbsnpfdb_" className="art:@container art:w-full art:min-w-0 art:space-y-5">
          <header className="art:flex art:flex-wrap art:items-end art:justify-between art:gap-4">
            <div>
              <h2 id="_R_pbsnpfdb_" className="art:text-2xl art:font-normal art:tracking-tight art:text-muted-foreground">
                {"Team performance"}
              </h2>
              <p className="art:mt-2 art:text-sm art:text-muted-foreground">
                {"A shared view of delivery, response, and review quality."}
              </p>
            </div>
            <div className="art:flex art:flex-wrap art:gap-2">
              <ChoiceMenu label="Performance team" icon={Users} value={team} options={TEAM_OPTIONS} onValueChange={setTeam}/>
              <ChoiceMenu label="Performance window" icon={CalendarDays} value={windowId} options={WINDOW_OPTIONS} onValueChange={setWindowId}/>
            </div>
          </header>
          <section aria-label="Key performance indicators" className="art:@container art:w-full art:min-w-0 art:@lg:[&>section>dl>div]:min-w-48">
            <section aria-label="Metric cards" tabIndex={0} className="art:overflow-x-auto art:rounded-2xl art:border art:border-border art:focus-visible:outline-none art:focus-visible:ring-2 art:focus-visible:ring-inset art:focus-visible:ring-ring">
              <dl className="art:flex art:flex-col art:gap-px art:bg-border art:@lg:w-max art:@lg:min-w-full art:@lg:flex-row">
                <div className={METRIC_CLASS}>
                  <div className="art:flex art:items-center art:gap-2">
                    <span aria-hidden="true" className={ICON_WRAP_CLASS}>
                      <svg xmlns="http://www.w3.org/2000/svg" width="24" height="24" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round" className="art:lucide art:lucide-check-check" aria-hidden="true">
                        <path d="M18 6 7 17l-5-5"/>
                        <path d="m22 10-7.5 7.5L13 16"/>
                      </svg>
                    </span>
                    <dt className={DT_CLASS}>{"Work delivered"}</dt>
                  </div>
                  <dd className={DD_CLASS}>
                    <div className="art:flex art:min-h-9 art:items-center art:gap-2">
                      <Roller className={VALUE_CLASS} text={grouped(totals.delivered)}/>
                    </div>
                    <p className="art:flex art:flex-wrap art:items-center art:gap-x-2 art:text-sm art:text-muted-foreground">
                      <span className={`art:font-mono art:font-medium art:tabular-nums ${totals.change.startsWith("-") ? "art:text-destructive" : "art:text-success-foreground"}`}>
                        <DeltaTicker value={totals.change}/>
                      </span>
                      <span>{"vs. previous period"}</span>
                    </p>
                  </dd>
                </div>
                <div className={METRIC_CLASS}>
                  <div className="art:flex art:items-center art:gap-2">
                    <span aria-hidden="true" className={ICON_WRAP_CLASS}>
                      <svg xmlns="http://www.w3.org/2000/svg" width="24" height="24" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round" className="art:lucide art:lucide-clock3 art:lucide-clock-3" aria-hidden="true">
                        <circle cx="12" cy="12" r="10"/>
                        <path d="M12 6v6h4"/>
                      </svg>
                    </span>
                    <dt className={DT_CLASS}>{"Replies on time"}</dt>
                  </div>
                  <dd className={DD_CLASS}>
                    <div className="art:flex art:min-h-9 art:items-center art:gap-2">
                      <Roller className={VALUE_CLASS} text={grouped(totals.replies[0])}/>
                    </div>
                    <p className="art:flex art:flex-wrap art:items-center art:gap-x-2 art:text-sm art:text-muted-foreground">
                      {`${pct(totals.replies)} of ${grouped(totals.replies[1])} replies`}
                    </p>
                  </dd>
                </div>
                <div className={METRIC_CLASS}>
                  <div className="art:flex art:items-center art:gap-2">
                    <span aria-hidden="true" className={ICON_WRAP_CLASS}>
                      <svg xmlns="http://www.w3.org/2000/svg" width="24" height="24" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round" className="art:lucide art:lucide-clipboard-check" aria-hidden="true">
                        <rect width="8" height="4" x="8" y="2" rx="1" ry="1"/>
                        <path d="M16 4h2a2 2 0 0 1 2 2v14a2 2 0 0 1-2 2H6a2 2 0 0 1-2-2V6a2 2 0 0 1 2-2h2"/>
                        <path d="m9 14 2 2 4-4"/>
                      </svg>
                    </span>
                    <dt className={DT_CLASS}>{"Reviews passed"}</dt>
                  </div>
                  <dd className={DD_CLASS}>
                    <div className="art:flex art:min-h-9 art:items-center art:gap-2">
                      <Roller className={VALUE_CLASS} text={grouped(totals.reviews[0])}/>
                    </div>
                    <p className="art:flex art:flex-wrap art:items-center art:gap-x-2 art:text-sm art:text-muted-foreground">
                      {`${pct(totals.reviews)} of ${grouped(totals.reviews[1])} reviews`}
                    </p>
                  </dd>
                </div>
              </dl>
            </section>
          </section>
          <div className="art:overflow-hidden art:rounded-2xl art:border art:border-border art:bg-background">
            <div className="art:flex art:flex-wrap art:items-center art:justify-between art:gap-3 art:p-5">
              <div>
                <h3 className="art:text-base art:font-normal art:text-muted-foreground">
                  {"Delivery leaderboard"}
                </h3>
                <p className="art:mt-1 art:text-xs art:text-muted-foreground">
                  {info.range}
                  {" \u00B7 "}
                  {String(ranked.length)}
                  {" teammates"}
                </p>
              </div>
              <div className="art:flex art:flex-col art:gap-1.5 art:w-full art:max-w-64">
                <div data-state={focused ? "focused" : "idle"} className={`art:relative art:h-10 art:overflow-hidden art:rounded-full art:border art:bg-background art:transition-colors art:duration-200 ${focused ? "art:border-foreground/60" : "art:border-border"}`}>
                  <span className="art:pointer-events-none art:absolute art:left-3 art:top-1/2 art:flex art:-translate-y-1/2 art:items-center art:text-muted-foreground art:[&_svg]:h-4 art:[&_svg]:w-4">
                    <svg xmlns="http://www.w3.org/2000/svg" width="24" height="24" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round" className="art:lucide art:lucide-search art:size-4" aria-hidden="true">
                      <path d="m21 21-4.34-4.34"/>
                      <circle cx="11" cy="11" r="8"/>
                    </svg>
                  </span>
                  <input id="_R_9epbsnpfdb_" type="search" aria-label="Find a teammate" placeholder="Find a teammate…" className="art:peer art:h-full art:w-full art:bg-transparent art:text-foreground art:caret-foreground art:outline-none art:pl-9 art:pr-4 art:text-sm art:placeholder:text-muted-foreground" value={query} onChange={(event) => setQuery(event.target.value)} onFocus={() => setFocused(true)} onBlur={() => setFocused(false)}/>
                </div>
                <div className="art:contents"/>
              </div>
            </div>
            <div className="art:w-full art:overflow-hidden art:bg-background art:text-sm art:border-0 art:border-t art:border-border art:[&_table]:min-w-5xl">
              <div className="art:overflow-auto art:[scrollbar-gutter:stable]" style={{ height: "448px" }}>
                <table className="art:min-w-[760px] art:w-full art:table-fixed art:border-collapse">
                  <colgroup>
                    <col style={{ width: "56px" }}/>
                    <col />
                    <col style={{ width: "135px" }}/>
                    <col style={{ width: "140px" }}/>
                    <col style={{ width: "170px" }}/>
                    <col style={{ width: "180px" }}/>
                    <col style={{ width: "80px" }}/>
                  </colgroup>
                  <thead>
                    <tr>
                      <th scope="col" className={`${TH_CLASS} art:text-left`}>
                        <span className="art:sr-only">{"Delivery rank"}</span>
                      </th>
                      {COLUMNS.map((column) => (<th key={column.key} scope="col" className={`${TH_CLASS} art:text-left`}>
                          <button type="button" className="art:inline-flex art:min-h-10 art:items-center art:gap-1.5 art:focus-visible:outline-none art:focus-visible:ring-2 art:focus-visible:ring-ring" onClick={() => toggleSort(column.key)}>
                            {column.label}
                            <SortIcon state={sort.key === column.key ? sort.dir : null}/>
                          </button>
                        </th>))}
                      <th scope="col" className={`${TH_CLASS} art:text-right`}>
                        <span className="art:sr-only">{"Teammate details"}</span>
                      </th>
                    </tr>
                  </thead>
                  <tbody>
                    {shown.length === 0 ? (<tr>
                        <td colSpan={7} className="art:h-48 art:px-6 art:text-center art:text-muted-foreground">
                          <p className="art:p-6 art:text-sm art:text-muted-foreground">{"No teammates match your search."}</p>
                        </td>
                      </tr>) : (shown.map(({ row, rank }) => {
            const t = row.teammate;
            const onTime = ratio(row.replies);
            const delta = change(row.delivered, row.previousDelivered);
            return (<tr key={t.name} className="art:border-border/70 art:border-b art:transition-colors art:last:border-b-0 art:hover:bg-muted/45 art:data-[selected]:bg-muted/70 art:cursor-pointer" style={{ height: "64px" }} onClick={() => setOpenName(t.name)}>
                            <td className="art:relative art:p-0 art:text-foreground art:text-left">
                              <div className={`${CELL_CLASS} art:justify-start`}>
                                <span className="art:text-xs art:tabular-nums art:text-muted-foreground">{String(rank).padStart(2, "0")}</span>
                              </div>
                            </td>
                            <td className="art:relative art:p-0 art:text-foreground art:text-left">
                              <div className={`${CELL_CLASS} art:justify-start`}>
                                <div className="art:flex art:items-center art:gap-3">
                                  <span aria-hidden="true" className="art:grid art:size-9 art:shrink-0 art:place-items-center art:rounded-full art:border art:border-border art:bg-muted art:text-xs art:text-muted-foreground">
                                    {t.initials}
                                  </span>
                                  <div className="art:min-w-0">
                                    <p className="art:truncate art:text-sm">{t.name}</p>
                                    <p className="art:mt-1 art:truncate art:text-xs art:text-muted-foreground">
                                      {t.team}
                                      {" \u00B7 "}
                                      {t.role}
                                    </p>
                                  </div>
                                </div>
                              </div>
                            </td>
                            <td className="art:relative art:p-0 art:text-foreground art:text-left">
                              <div className={`${CELL_CLASS} art:justify-start`}>
                                <div className="art:space-y-1">
                                  <p className="art:text-sm art:tabular-nums">{String(row.delivered)}</p>
                                  <p className="art:text-xs art:tabular-nums art:text-muted-foreground">{`${delta}%`}</p>
                                </div>
                              </div>
                            </td>
                            <td className="art:relative art:p-0 art:text-foreground art:text-left">
                              <div className={`${CELL_CLASS} art:justify-start`}>
                                <span className="art:text-sm art:tabular-nums art:text-muted-foreground">{row.firstReply}</span>
                              </div>
                            </td>
                            <td className="art:relative art:p-0 art:text-foreground art:text-left">
                              <div className={`${CELL_CLASS} art:justify-start`}>
                                <div className="art:w-full art:max-w-32 art:space-y-2">
                                  <p className="art:text-xs art:tabular-nums">{pct(row.replies)}</p>
                                  <div role="progressbar" aria-label={`${t.name} replies on time`} aria-valuemin={0} aria-valuemax={100} aria-valuenow={Math.round(onTime * 100)} className="art:h-1.5 art:overflow-hidden art:rounded-full art:bg-muted">
                                    <OnTimeBar value={onTime}/>
                                  </div>
                                </div>
                              </div>
                            </td>
                            <td className="art:relative art:p-0 art:text-foreground art:text-left">
                              <div className={`${CELL_CLASS} art:justify-start`}>
                                <span className="art:text-sm art:tabular-nums art:text-muted-foreground">{pct(row.reviews)}</span>
                              </div>
                            </td>
                            <td className="art:relative art:p-0 art:text-foreground art:text-right">
                              <div className={`${CELL_CLASS} art:justify-end`}>
                                <motion.button type="button" className={VIEW_BUTTON_CLASS} aria-label={`View performance for ${t.name}`} tabIndex={0} whileHover={reduce ? undefined : { scale: 1.01 }} whileTap={reduce ? undefined : { scale: 0.99 }} transition={ARTEMIS_SPRING_PRESS} onClick={(event) => {
                    event.stopPropagation();
                    setOpenName(t.name);
                }}>
                                  <svg xmlns="http://www.w3.org/2000/svg" width="24" height="24" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round" className="art:lucide art:lucide-arrow-up-right art:size-4" aria-hidden="true">
                                    <path d="M7 7h10v10"/>
                                    <path d="M7 17 17 7"/>
                                  </svg>
                                </motion.button>
                              </div>
                            </td>
                          </tr>);
        }))}
                  </tbody>
                </table>
              </div>
            </div>
            <footer className="art:flex art:flex-wrap art:justify-between art:gap-2 art:border-t art:border-border art:px-5 art:py-3 art:text-xs art:text-muted-foreground">
              <span>{"Rank is based on delivered work. Reply and review rates use their own sample counts."}</span>
              <span>
                {String(shown.length)}
                {" shown"}
              </span>
            </footer>
          </div>
          <p className="art:text-xs art:text-muted-foreground">
            {"Delivery changes compare with "}
            {info.previousRange}
            {". Missing days have no percentage baseline."}
          </p>
        </section>
        <p className="art:mt-4 art:text-xs art:text-muted-foreground">
          {"Sample workspace \u00B7 Observations through Sep 30, 2026"}
        </p>
      </div>
      <TeammateDialog row={openRow} windowId={windowId} onClose={() => setOpenName(null)}/>
    </>);
}

"use client";
// @zeus-internal
import { Check, ChevronDown, type LucideIcon } from "lucide-react";
import { motion, type Transition } from "motion/react";
import { type CSSProperties, type KeyboardEvent, type PointerEvent, useCallback, useEffect, useId, useLayoutEffect, useRef, useState, } from "react";
import { artemisCreatePortal } from "../../../../artemis-scope";
import { ARTEMIS_SPRING_LAYOUT } from "../../../../lib/ease";
import { acquireFocusGuards, hideOthers, lockBodyScroll } from "./modal-layer";
const SIDE_OFFSET = 8;
const COLLISION_PADDING = 12;
const MENU_MIN_WIDTH = 192;
const HIGHLIGHT_TRANSITION: Transition = ARTEMIS_SPRING_LAYOUT;
const DROPDOWN_CSS = `
  @keyframes artemis-72e2b8e-artemis-dropdown-panel-enter {
    from {
      opacity: 0;
      transform: scale(0.96);
    }
    to {
      opacity: 1;
      transform: scale(1);
    }
  }

  @keyframes artemis-72e2b8e-artemis-dropdown-panel-exit {
    from {
      opacity: 1;
      transform: scale(1);
    }
    to {
      opacity: 0;
      transform: scale(0.96);
    }
  }

  @keyframes artemis-72e2b8e-artemis-dropdown-clip-enter {
    from {
      clip-path: var(--artemis-dropdown-hidden-clip);
    }
    to {
      clip-path: inset(0% 0% 0% 0% round 12px);
    }
  }

