const DAY_MS = 86400000;
const SERIES_START = Date.UTC(2026, 8, 3);
export type WindowInfo = {
    days: number;
    currentStart: number;
    previousStart: number;
    range: string;
    previousRange: string;
    xTicks: string[];
};
export const WINDOWS: Record<WindowId, WindowInfo> = {
    "28": {
        days: 28,
        currentStart: SERIES_START,
        previousStart: Date.UTC(2026, 7, 6),
        range: "Sep 3 \u2013 Sep 30, 2026",
        previousRange: "Aug 6 \u2013 Sep 2, 2026",
        xTicks: ["Day 1", "Day 7", "Day 13", "Day 19", "Day 28"],
    },
    "7": {
        days: 7,
        currentStart: SERIES_START + 21 * DAY_MS,
        previousStart: SERIES_START + 14 * DAY_MS,
        range: "Sep 24 \u2013 Sep 30, 2026",
        previousRange: "Sep 17 \u2013 Sep 23, 2026",
        xTicks: ["Day 1", "Day 3", "Day 5", "Day 7"],
    },
};
export type Row = {
    teammate: Teammate;
    delivered: number;
    previousDelivered: number;
    firstReply: string;
    firstReplyMinutes: number;
    replies: [
        number,
        number
    ];
    reviews: [
        number,
        number
    ];
    current: number[];
    previous: number[];
};
const sum = (values: number[]) => values.reduce((a, b) => a + b, 0);
export function rowFor(teammate: Teammate, windowId: WindowId): Row {
    const current = windowId === "28" ? teammate.current : teammate.current.slice(21);
    const previous = windowId === "28" ? teammate.previous : teammate.current.slice(14, 21);
    const stats = teammate.stats[windowId];
    return {
        teammate,
        delivered: sum(current),
        previousDelivered: sum(previous),
        firstReply: stats.firstReply,
        firstReplyMinutes: Number.parseFloat(stats.firstReply),
        replies: stats.replies,
        reviews: stats.reviews,
        current,
        previous,
    };
}
export const pct = ([part, whole]: [
    number,
    number
]) => `${((part / whole) * 100).toFixed(1)}%`;
export function change(current: number, previous: number): string {
    const value = ((current - previous) / previous) * 100;
    const text = Math.abs(value).toFixed(1);
    if (text === "0.0")
        return "0.0";
    return `${value > 0 ? "+" : "-"}${text}`;
}

